import{_ as n,c as a,o as e,ag as p}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Linux Server Initial Setup","description":"","frontmatter":{"title":"Linux Server Initial Setup"},"headers":[],"relativePath":"server-guides/linux-server-initial-setup.md","filePath":"server-guides/linux-server-initial-setup.md","lastUpdated":null}'),l={name:"server-guides/linux-server-initial-setup.md"};function i(r,s,t,c,o,u){return e(),a("div",null,[...s[0]||(s[0]=[p(`<h1 id="linux-server-initial-setup" tabindex="-1">Linux Server Initial Setup <a class="header-anchor" href="#linux-server-initial-setup" aria-label="Permalink to &quot;Linux Server Initial Setup&quot;">​</a></h1><h2 id="installing-docker-and-setting-up-the-system" tabindex="-1">Installing Docker and Setting Up the System <a class="header-anchor" href="#installing-docker-and-setting-up-the-system" aria-label="Permalink to &quot;Installing Docker and Setting Up the System&quot;">​</a></h2><p>This guide introduces setting up a server with Docker and organizing sections to help users get started with development environments.</p><h3 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h3><ul><li><p><strong>From Source on a Computer</strong>: Direct installation on a local system.</p></li><li><p><strong>Within a Dockerfile</strong>: Create a base Dockerfile for repeatable setups.</p></li><li><p><strong>Remotely with Ansible</strong>: Automate Docker setup across multiple servers.</p></li><li><p><strong>Without Docker</strong>: General system preparation without Docker.</p></li></ul><h3 id="from-source-on-a-computer" tabindex="-1">From Source on a Computer <a class="header-anchor" href="#from-source-on-a-computer" aria-label="Permalink to &quot;From Source on a Computer&quot;">​</a></h3><p>Source: <a href="https://docs.docker.com/engine/install/debian/#install-using-the-repository" target="_blank" rel="noreferrer">Docker Official Documentation</a></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Step 1: Install sudo and update the system</span></span>
<span class="line"><span>apt install -y sudo</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt upgrade -y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Step 2: Enable unattended-upgrades</span></span>
<span class="line"><span>sudo apt install -y unattended-upgrades</span></span>
<span class="line"><span>sudo sh -c &#39;echo &quot;APT::Periodic::Update-Package-Lists \\&quot;1\\&quot;; APT::Periodic::Unattended-Upgrade \\&quot;1\\&quot;;&quot; &gt; /etc/apt/apt.conf.d/20auto-upgrades&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Step 3: Install basic tools</span></span>
<span class="line"><span>sudo apt install -y git ca-certificates curl rsync pass p7zip-full unzip fail2ban ufw</span></span>
<span class="line"><span>sudo install -m 0755 -d /etc/apt/keyrings</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Step 4: Set up Docker</span></span>
<span class="line"><span>sudo curl -fsSL https://download.docker.com/linux/debian/gpg -o /etc/apt/keyrings/docker.asc</span></span>
<span class="line"><span>sudo chmod a+r /etc/apt/keyrings/docker.asc</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Add the Docker repository to Apt sources</span></span>
<span class="line"><span>echo &quot;deb [--print-architecture) signed-by=/etc/apt/keyrings/docker.asc](arch=$(dpkg) https://download.docker.com/linux/debian \\</span></span>
<span class="line"><span>$(. /etc/os-release &amp;&amp; echo &quot;$VERSION_CODENAME&quot;) stable&quot; | sudo tee /etc/apt/sources.list.d/docker.list &gt; /dev/null</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Step 5: Install Docker</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Step 6: Add current user to the Docker group</span></span>
<span class="line"><span>sudo usermod -aG docker $USER</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><h3 id="remotely-setting-up-with-ansible" tabindex="-1">Remotely Setting Up with Ansible <a class="header-anchor" href="#remotely-setting-up-with-ansible" aria-label="Permalink to &quot;Remotely Setting Up with Ansible&quot;">​</a></h3><p>Automate Docker setup on remote servers using this Ansible playbook:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>- name: Install Docker on remote servers</span></span>
<span class="line"><span>  hosts: all</span></span>
<span class="line"><span>  become: yes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - name: Update and upgrade the system</span></span>
<span class="line"><span>      apt:</span></span>
<span class="line"><span>        update_cache: yes</span></span>
<span class="line"><span>        upgrade: dist</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    - name: Install essential packages</span></span>
<span class="line"><span>      apt:</span></span>
<span class="line"><span>        name:</span></span>
<span class="line"><span>          - sudo</span></span>
<span class="line"><span>          - git</span></span>
<span class="line"><span>          - ca-certificates</span></span>
<span class="line"><span>          - curl</span></span>
<span class="line"><span>          - rsync</span></span>
<span class="line"><span>          - p7zip-full</span></span>
<span class="line"><span>          - unzip</span></span>
<span class="line"><span>        state: present</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    - name: Add Docker GPG key</span></span>
<span class="line"><span>      command: &gt;</span></span>
<span class="line"><span>        curl -fsSL https://download.docker.com/linux/debian/gpg -o /usr/share/keyrings/docker.gpg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    - name: Add Docker repository</span></span>
<span class="line"><span>      lineinfile:</span></span>
<span class="line"><span>        path: /etc/apt/sources.list.d/docker.list</span></span>
<span class="line"><span>        line: &gt;</span></span>
<span class="line"><span>          deb [ansible_architecture }} signed-by=/usr/share/keyrings/docker.gpg](arch={{)</span></span>
<span class="line"><span>          https://download.docker.com/linux/debian  stable</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    - name: Install Docker</span></span>
<span class="line"><span>      apt:</span></span>
<span class="line"><span>        name:</span></span>
<span class="line"><span>          - docker-ce</span></span>
<span class="line"><span>          - docker-ce-cli</span></span>
<span class="line"><span>          - containerd.io</span></span>
<span class="line"><span>        state: present</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    - name: Add user to Docker group</span></span>
<span class="line"><span>      user:</span></span>
<span class="line"><span>        name: &quot;&quot;</span></span>
<span class="line"><span>        groups: docker</span></span>
<span class="line"><span>        append: yes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br></div></div><h3 id="without-docker" tabindex="-1">Without Docker <a class="header-anchor" href="#without-docker" aria-label="Permalink to &quot;Without Docker&quot;">​</a></h3><p>If Docker is not needed, follow these steps for a basic system setup:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>1. Step 1: Install sudo and update the system</span></span>
<span class="line"><span>apt install -y sudo</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt upgrade -y</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Step 2: Install basic tools</span></span>
<span class="line"><span>sudo apt install -y git ca-certificates curl rsync pass p7zip-full unzip fail2ban ufw</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Step 3: Enable unattended-upgrades</span></span>
<span class="line"><span>sudo apt install -y unattended-upgrades</span></span>
<span class="line"><span>sudo sh -c &#39;echo &quot;APT::Periodic::Update-Package-Lists \\&quot;1\\&quot;; APT::Periodic::Unattended-Upgrade \\&quot;1\\&quot;;&quot; &gt; /etc/apt/apt.conf.d/20auto-upgrades&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Step 4: Reload necessary services</span></span>
<span class="line"><span>systemctl reload postfix</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3>`,15)])])}const m=n(l,[["render",i]]);export{d as __pageData,m as default};
